def countEvenPopcount(n):
    result = 0
    ones = 0
    for i in range(n.bit_length() - 1, -1, -1):
        if (n >> i) & 1:
            if i == 0:
                result += 1 if ones % 2 == 0 else 0
            else:
                result += 1 << (i - 1)
            ones += 1
    if ones % 2 == 0:
        result += 1
    return result
